package br.com.tapeteskalke.service; import br.com.tapeteskalke.dto.OperacaoDtos.*; import br.com.tapeteskalke.entity.*; import br.com.tapeteskalke.exception.*; import br.com.tapeteskalke.repository.*; import br.com.tapeteskalke.security.CurrentUser; import br.com.tapeteskalke.util.Normalizer; import java.time.*; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
// O ENTREGADOR é vinculado ao cadastro de funcionário pelo e-mail: só enxerga e atualiza as entregas atribuídas a ele.
@Service public class EntregaService { private final EntregaRepository deliveries; private final VendaRepository sales; private final FuncionarioRepository employees; private final PermissionService permissions; private final CurrentUser current; private final Clock clock; public EntregaService(EntregaRepository deliveries,VendaRepository sales,FuncionarioRepository employees,PermissionService permissions,CurrentUser current,Clock clock){this.deliveries=deliveries;this.sales=sales;this.employees=employees;this.permissions=permissions;this.current=current;this.clock=clock;} @Transactional public EntregaResponse create(EntregaRequest r){permissions.action("entregas_criar");if(deliveries.existsByVendaId(r.vendaId()))throw new BusinessException("ENTREGA_DUPLICADA","Já existe entrega para esta venda",HttpStatus.CONFLICT);var sale=sales.detail(r.vendaId()).orElseThrow(()->new ResourceNotFoundException("Venda",r.vendaId()));if(!"FINALIZADA".equals(sale.getStatus()))throw new BusinessException("VENDA_CANCELADA","Não é possível entregar venda cancelada",HttpStatus.CONFLICT);var c=sale.getCliente();var e=new Entrega();e.setVenda(sale);e.setCliente(c);e.setEnderecoEntrega(defaultValue(r.enderecoEntrega(),c.getEndereco()));e.setBairro(defaultValue(r.bairro(),c.getBairro()));e.setCidade(defaultValue(r.cidade(),c.getCidade()));e.setCep(Normalizer.digits(defaultValue(r.cep(),c.getCep())));e.setTelefoneContato(Normalizer.digits(defaultValue(r.telefoneContato(),c.getTelefone())));e.setDataAgendada(r.dataAgendada());e.setHorario(r.horario());e.setEntregador(r.entregadorId()==null||r.entregadorId().isBlank()?null:employees.findById(r.entregadorId()).filter(f->f.getDeletedAt()==null).orElseThrow(()->new ResourceNotFoundException("Entregador",r.entregadorId())));e.setValorFrete(r.valorFrete()==null?java.math.BigDecimal.ZERO:r.valorFrete());e.setObservacoes(r.observacoes());e.setCreatedBy(current.require().id());e.setUpdatedBy(current.require().id());return response(deliveries.save(e));}
 @Transactional public EntregaResponse status(String id,EntregaStatusRequest r){permissions.action("entregas_atualizar_status");var e=deliveries.detail(id).orElseThrow(()->new ResourceNotFoundException("Entrega",id));if(isDriver()&&!assignedToMe(e))throw new AccessDeniedBusinessException("Esta entrega não está atribuída a você");if("ENTREGUE".equals(e.getStatus()))throw new BusinessException("ENTREGA_FINALIZADA","Entrega já está finalizada",HttpStatus.CONFLICT);if("CANCELADA".equals(e.getStatus()))throw new BusinessException("ENTREGA_CANCELADA","A venda desta entrega foi cancelada",HttpStatus.CONFLICT);if("EM_ROTA".equals(r.status())&&!"AGENDADA".equals(e.getStatus()))throw new BusinessException("TRANSICAO_INVALIDA","Transição de status inválida",HttpStatus.CONFLICT);if("ENTREGUE".equals(r.status())&&!("AGENDADA".equals(e.getStatus())||"EM_ROTA".equals(e.getStatus())))throw new BusinessException("TRANSICAO_INVALIDA","Transição de status inválida",HttpStatus.CONFLICT);e.setStatus(r.status());if("ENTREGUE".equals(r.status()))e.setDataEntrega(OffsetDateTime.now(clock));e.setUpdatedBy(current.require().id());return response(e);}
 @Transactional(readOnly=true) public List<EntregaResponse> list(){var list=isDriver()?deliveries.byDriverEmail(current.require().email()):deliveries.allDetailed();return list.stream().map(this::response).toList();}
 private boolean isDriver(){return current.hasRole("ENTREGADOR");}
 private boolean assignedToMe(Entrega e){return e.getEntregador()!=null&&e.getEntregador().getEmail()!=null&&e.getEntregador().getEmail().equalsIgnoreCase(current.require().email());}
 private String defaultValue(String supplied,String fallback){return supplied==null||supplied.isBlank()?fallback:supplied;} private EntregaResponse response(Entrega e){return new EntregaResponse(e.getId(),e.getCliente().getNome(),e.getVenda().getId(),e.getVenda().getNumeroVenda(),e.getEntregador()==null?null:e.getEntregador().getNome(),e.getStatus(),e.getDataAgendada(),e.getHorario(),e.getDataEntrega());} }
